    let app_jwt = sign_app_jwt(app_id, private_key)?;
    let response = CLIENT
        .get(format!("{api_base}/app"))
        .header("User-Agent", "preloop")
        .header("Authorization", format!("Bearer {app_jwt}"))
        .header("Accept", "application/vnd.github+json")
